sealed trait Result[+A]
object Result { case class Ok[A](a: A) extends Result[A]; case class Err(e: E) extends Result[Nothing] }

// adding a case to a sealed trait = compile error at every non-exhaustive match
def render(r: Result[String]): String = r match {
  case Ok(a)  => a
  case Err(e) => e.msg        // exhaustive: compiler enforces it
}
